      : [];

    return lista.length >= cantidad_limite_frm_gen_lista_intermediarios_adicionales ? "true" : "false";

const root = document.querySelector('[selector="list-gen-intermediarios-adicionales"]');
if (!root) return;

const table   = root.querySelector('table.record-list-table-secondary');
const wrapper = root.querySelector('.data-table');

if (!table || !wrapper) return;

const updateMaxRowsState = () => {
  const rows = table.querySelectorAll('tbody tr').length;
  if (rows >= 5) {
    wrapper.classList.add('max-rows');
  } else {
    wrapper.classList.remove('max-rows');
  }
};

updateMaxRowsState();

const rows = this.frm_gen_lista_intermediarios_adicionales || [];

if (!Array.isArray(rows)) return "false";

const seen = new Set();

for (const r of rows) {
  const nombre_intermediario = (r.frm_gen_nombre_intermediario || "")
    .trim()
    .toLowerCase();

  if (!nombre_intermediario) continue; // ignora vacíos o null

  if (seen.has(nombre_intermediario)) return "true"; // duplicado encontrado
  seen.add(nombre_intermediario);
}

return "false";

const rows = this.frm_gen_lista_intermediarios_adicionales || [];
if (!Array.isArray(rows)) return "";

const counts = new Map();

for (const r of rows) {
  const nombre_intermediario = (r.frm_gen_nombre_intermediario || "")
    .trim();

  if (!nombre_intermediario) continue;

  counts.set(nombre_intermediario, (counts.get(nombre_intermediario) || 0) + 1);
}

const duplicates = [];
for (const [nombre_intermediario, n] of counts.entries()) {
  if (n > 1) duplicates.push(nombre_intermediario);
}

return duplicates.join(", "); // ejemplo: "a@x.com, b@y.com"

