setTimeout(() => {
  const modalComponent = document.querySelector(
    '[custom-css-selector="btn_preventivo"]'
  );

  if (!modalComponent || !modalComponent.__vue__) {
    return;
  }

  const vueInstance = modalComponent.__vue__;

  vueInstance.$root.$on("bv::modal::show", (bvEvent, modalId) => {
    const modal = bvEvent.vueTarget;

    if (modalId === "modal_preventivo") {
      modal.onOk = () => {
        const loader = document.getElementById("global-loader-overlay");
        const submitBtn = document.querySelector(
          'button[name="btn_submit_real"]'
        );

        const frm_decision_evaluacion_riesgo = this.frm_decision_evaluacion_riesgo;

        if (frm_decision_evaluacion_riesgo == "CONTINUAR") {
          const frm_riesgo_validezDias = this.frm_riesgo_validezDias;
          if (frm_riesgo_validezDias == null || frm_riesgo_validezDias == "") {
            vueInstance.$root.$bvModal.show("modal_requiere_decision_continuar");
            modal.hide();
            return;
          }
        }

        /* Validación de errores visibles ANTES del submit */
        const erroresCustom        = document.querySelectorAll('[selector="text-invalid"]');
        const erroresCustomTable   = document.querySelectorAll('[selector="text-invalid-in-table"]');
        const erroresBootstrap     = document.querySelectorAll(".invalid-feedback");
        const erroresVisibles      = [];

        erroresCustom.forEach((div) => {
          const visible = div.offsetParent !== null;
          const mensaje = div.textContent.trim().toLowerCase();
          if (visible) erroresVisibles.push(mensaje);
        });

        erroresCustomTable.forEach((div) => {
          const visible = div.offsetParent !== null;
          const mensaje = div.textContent.trim().toLowerCase();
          if (visible) erroresVisibles.push(mensaje);
        });

        erroresBootstrap.forEach((div) => {
          const visible = div.offsetParent !== null;
          const mensaje = div.textContent.trim().toLowerCase();
          if (visible) erroresVisibles.push(mensaje);
        });

        if (erroresVisibles.length > 0) {
          if (loader) loader.classList.remove("show");
          vueInstance.$root.$bvModal.show("modal_accion_requerida");
          modal.hide();
          return;
        }
        /* Fin validación de errores visibles */

        if (loader) loader.classList.add("show");

        if (submitBtn) {
          submitBtn.click();
        }

        modal.hide();
      };
    }
  });
}, 500);

setTimeout(() => {
  const modalComponent = document.querySelector(
    '[custom-css-selector="css_modal_nueva_opcion"]'
  );

  if (!modalComponent || !modalComponent.__vue__) {
    return;
  }

  const vueInstance = modalComponent.__vue__;

  vueInstance.$root.$on("bv::modal::show", (bvEvent, modalId) => {
    const modal = bvEvent.vueTarget;

    if (modalId === "modal_nueva_opcion") {
      modal.onOk = () => {
        const loader = document.getElementById("global-loader-overlay");

        const submitBtn = document.querySelector(
          'button[name="frm_decision_evaluacion_riesgo_nueva_opcion"]'
        );

        //console.log("antes del procede");

        const frm_valor_asegurado_control_procede =
          vueInstance.frm_valor_asegurado_control_procede;

        if (frm_valor_asegurado_control_procede == false) {
          vueInstance.$root.$bvModal.show(
            "modal_alert_valorAsegDeduc_alMenosUnValor"
          );

          modal.hide();

          if (loader) loader.classList.remove("show");

          return;
        }

        /* -------------------------
        VALIDACIÓN ACTUAL DE ERRORES
        --------------------------*/

        //console.log("validando errores visibles");

        const erroresCustom = document.querySelectorAll(
          '[selector="text-invalid"]'
        );
        const erroresBootstrap =
          document.querySelectorAll(".invalid-feedback");

        const erroresVisibles = [];

        erroresCustom.forEach((div) => {
          const visible = div.offsetParent !== null;
          const mensaje = div.textContent.trim().toLowerCase();

          if (visible) {
            erroresVisibles.push(mensaje);
          }
        });

        erroresBootstrap.forEach((div) => {
          const visible =
            div.offsetParent !== null &&
            div.classList.contains("d-block");

          const mensaje = div.textContent.trim().toLowerCase();

          if (visible) {
            erroresVisibles.push(mensaje);
          }
        });

        if (erroresVisibles.length > 0) {
          //console.log("errores detectados antes del submit");

          if (loader) loader.classList.remove("show");

          vueInstance.$root.$bvModal.show("modal_accion_requerida");

          modal.hide();

          return;
        }

        /* -------------------------
        SI NO HAY ERRORES → SUBMIT
        --------------------------*/

        //console.log("sin errores, ejecutando submit");

        if (submitBtn) {
          submitBtn.click();
        }

        /* -------------------------
        ESPERAR Y REVISAR ALERT HTML
        --------------------------*/

        setTimeout(() => {
          const alertError = document.querySelector(
            '.alert.alert-danger[role="alert"]'
          );

          if (
            alertError &&
            alertError.textContent
              .toLowerCase()
              .includes("errores de validación")
          ) {
            //console.log("alert de errores detectado después del submit");

            if (loader) loader.classList.remove("show");

            vueInstance.$root.$bvModal.show("modal_accion_requerida");

            modal.hide();

            return;
          }

          //console.log("no apareció alert, continuar flujo");

          if (loader) loader.classList.add("show");
        }, 400);

        modal.hide();
      };
    }
  });
}, 500);

// Calculated Property (JavaScript): autoPageIndex
// Supón que this.tabDestino vale: "INICIO", "COBERTURAS", "PRICING", "Resumen", "Términos y condiciones"

const raw = (this.tabDestino || "").toString().trim();

// Mapea etiquetas a índices (ajusta si tu orden de páginas difiere)
const map = {
  "INICIO": 0,
  "COBERTURAS": 1,
  "PRICING": 2,
  "RESUMEN": 3,
  "TÉRMINOS Y CONDICIONES": 4,
  "TERMINOS Y CONDICIONES": 4, // por si llega sin tilde
};

const key = raw.toUpperCase();
const target = (key in map) ? map[key] : 0;

// Guarda para no “pelear” contra el usuario si ya está en esa página
if (typeof this.currentPage__ !== "undefined" && this.currentPage__ !== target) {
  // Método nativo del multi-page (si existe)
  if (typeof this.pageNavigate === "function") {
    this.pageNavigate(target);
  } else {
    // Fallback: set directo
    this.currentPage__ = target;
  }
}

return target;

