return this.frm_cot_retroactividad;

const toDate = (s) => (s ? new Date(`${s}T00:00:00`) : null);

const solicitudStr = this.frm_control_fecha_hoy;
const retroStr = this.frm_cot_retroactividad;

const end = toDate(solicitudStr);
const start = toDate(retroStr);

if (!start || !end) return null;
if (end < start) return 0;

let months =
  (end.getFullYear() - start.getFullYear()) * 12 +
  (end.getMonth() - start.getMonth());

if (end.getDate() < start.getDate()) months -= 1;
if (months < 0) months = 0;

const years = Math.floor(months / 12) + ((months % 12) > 6 ? 1 : 0);

return years;

