      const dialog = container.querySelector('div[role="dialog"]');
      if (!dialog) return false;

      const inlineDisplay = dialog.style?.display;
      const display =
        inlineDisplay && inlineDisplay.trim() !== ""
          ? inlineDisplay
          : window.getComputedStyle(dialog).display;

      return display !== "none";
    };

    // 1) Encuentra la modal activa (add/edit)
    const containers = document.querySelectorAll(
      '[data-cy="modal-add"], [data-cy="modal-edit"]'
    );

    let activeContainer = null;
    for (const c of containers) {
      if (isContainerVisible(c)) {
        activeContainer = c;
        break;
      }
    }
    if (!activeContainer) return;

    // 2) Modal dialog + botón Aceptar
    const modalDialog = activeContainer.querySelector(".modal-dialog");
    if (!modalDialog) return;

    const aceptarBtn = modalDialog.querySelector(
      ".modal-footer button.btn.btn-primary"
    );
    if (!aceptarBtn) return;

    // 3) Función: hay errores visibles en ESTA modal
    const tieneErroresVisibles = () => {
      const invalids = Array.from(
        modalDialog.querySelectorAll(".invalid-feedback")
      );

      return invalids.some((div) => {
        const style = window.getComputedStyle(div);
        const visible =
          style.display !== "none" &&
          style.visibility !== "hidden" &&
          style.opacity !== "0";

        const msg = (div.textContent || "").trim();
        return visible && msg;
      });
    };

    // 4) Deshabilita botón si hay errores
    const hayError = tieneErroresVisibles();
    aceptarBtn.disabled = hayError;
    aceptarBtn.classList.toggle("disabled", hayError);

    // 5) Bloquea click (por si Vue igual intenta avanzar)
    if (!aceptarBtn._modalErrorGuard) {
      aceptarBtn._modalErrorGuard = true;

      aceptarBtn.addEventListener(
        "click",
        (e) => {
          if (tieneErroresVisibles()) {
            e.stopImmediatePropagation?.();
            e.stopPropagation();
            e.preventDefault();
            return false;
          }
        },
        true // captura
      );
    }
  } catch (e) {}
}, 0);

